use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a (year, month, day) civil date
/// (proleptic Gregorian; Howard Hinnant's algorithm).
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

/// Format seconds since the Unix epoch as `YYYY-MM-DD`, always exactly
/// 10 characters (years are clamped to 0000..=9999).
fn date_from_seconds(seconds: u64) -> String {
    // u64::MAX / 86400 < 2^48, so this fits in i64 without overflow.
    let days = (seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let s = if y > 9_999 {
        String::from("9999-12-31")
    } else if y < 0 {
        String::from("0000-01-01")
    } else {
        format!("{:04}-{:02}-{:02}", y, m, d)
    };
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let date = date_from_seconds(started);
        RunInfo { date, started }
    }
}

export!(Node);
